import { AutociteEvent, AutociteRequest, AUTOCITE_JOB_TTL, JobFailedStatuses } from "@cgs/types";
import { UnreachableCaseError } from "@cgs/utils";
import { fetchJson } from "./fetch";

// Polyfill for AbortSignal.timeout
if (!AbortSignal.timeout) {
  AbortSignal.timeout = (ms) => {
    const controller = new AbortController();
    setTimeout(() => controller.abort(new DOMException("TimeoutError")), ms);
    return controller.signal;
  };
}

function getAutociteBaseUrl() {
  if (process.env.NODE_ENV === "development") {
    return "http://localhost:4001";
  }

  return (
    (typeof window !== "undefined" && window.env?.AUTOCITE_BASE_URL) ||
    process.env.AUTOCITE_BASE_URL ||
    "https://autocite.cgs.scribbr.com"
  );
}

export async function autocite(
  request: AutociteRequest,
  opts?: RequestInit,
  host = getAutociteBaseUrl(),
): Promise<AutociteEvent> {
  const signal = AbortSignal.timeout(AUTOCITE_JOB_TTL + 1000);
  // If we are uploading form data, we don't want to set the content type header
  // This is because the browser will automatically set the content type header
  // And it will include the boundary which is necessary for the server to parse the form data
  const isFormDataBody = opts?.body?.valueOf().constructor.name === "FormData";
  const contentTypeHeader: Record<string, string> = {
    ...(!isFormDataBody ? { "Content-Type": "application/json" } : {}),
  };
  try {
    const { eventSourceURL } = await fetchJson(`${host}/autocite`, {
      signal,
      method: "post",
      headers: {
        Accept: "application/json",
        ...contentTypeHeader,
        ...opts?.headers,
      },
      body: JSON.stringify(request),
      ...opts,
    });

    return new Promise<AutociteEvent>((resolve) => {
      const handleEvent = (event: AutociteEvent) => {
        eventSource?.close();

        const { type, data } = event;

        switch (type) {
          case "sources":
          case "abstract":
          case "failed":
          case "forbidden":
          case "timeout":
          case "external_server_error":
          case "invalid_resource":
            return resolve(event);
          default:
            // just here for typechecking, falling back to failed state
            new UnreachableCaseError(type);

            return resolve({ type: "failed", data });
        }
      };

      const abort = () => {
        handleEvent({ type: "timeout", data: "Autocite request timed out" });
      };

      signal?.addEventListener("abort", abort);

      const eventSource = new EventSource(eventSourceURL);
      eventSource.onerror = () => {
        handleEvent({ type: "failed", data: "Failed to connect" });
      };

      eventSource.onmessage = (message) => {
        try {
          handleEvent(JSON.parse(message.data) as AutociteEvent);
        } catch (e) {
          handleEvent({ type: "failed", data: "Failed to parse event" });
        }
      };

      // the server is still sending specific events so this adds backwards compatibility with the current server
      eventSource.addEventListener("sources", (event) => {
        try {
          handleEvent({ type: "sources", data: JSON.parse(event.data) });
        } catch (e) {
          handleEvent({ type: "failed", data: "Failed to parse sources" });
        }
      });

      for (const failedStatus of JobFailedStatuses) {
        eventSource.addEventListener(failedStatus, (event) => {
          handleEvent({ type: failedStatus, data: event.data });
        });
      }
    });
  } catch (e) {
    if (e instanceof Error && e.name === "AbortError") {
      return Promise.resolve({
        type: "timeout",
        data: "Autocite request timed out",
      });
    }

    throw e;
  }
}
