import { SourceType, SourceTypes, Domain, ScribbrEnv } from "@cgs/types";
import { getScribbrHost, isSourceType } from "../utils";
import { shortenID } from "../id";

type QueryParams = {
  searchQuery?: string;
  sourceType?: SourceType;
  version?: string;
};

type QueryParamEncoding = {
  [Param in keyof Required<QueryParams>]: {
    encode: (value: Exclude<QueryParams[Param], undefined>) => string;
    decode: (value: string) => Exclude<QueryParams[Param], undefined> | null;
  };
};

type EncodedQueryParams = {
  [Param in keyof QueryParams]: string;
};

const stringEncoding = (value: string) => value;

const queryParamEncoders: QueryParamEncoding = {
  searchQuery: {
    encode: stringEncoding,
    decode: stringEncoding,
  },
  sourceType: {
    encode: (value: SourceType) => value,
    decode: (value: string) => (isSourceType(value) ? value : null),
  },
  version: {
    encode: stringEncoding,
    decode: stringEncoding,
  },
};

type Segment = [param: string, value: string | undefined] | string;

export class RouteBuilder {
  private segments: Array<Segment> = [];
  private queryParams: EncodedQueryParams = {};

  constructor(public readonly domain: Domain) {
    const roots: Record<Domain, string> = {
      com: "citation/generator",
      "co.uk": "referencing/generator",
      nl: "bronvermelding/generator",
      de: "zitieren/generator",
      at: "zitieren/generator",
      ch: "zitieren/generator",
      fr: "references/generateur",
      dk: "reference/generator",
      es: "citar/generador",
      it: "citare/generatore",
    };
    this.segments.push(roots[domain]);
  }

  style(styleSlug: string) {
    return this.segment(styleSlug);
  }

  styleLandingPages() {
    return {
      com: ["apa", "mla", "chicago", "ieee", "ama", "acs"],
      "co.uk": ["apa", "harvard"],
      nl: ["apa", "mla"],
      de: ["apa", "mla", "harvard", "fussnoten"],
      at: ["apa", "harvard", "fussnoten"],
      ch: ["apa", "harvard", "fussnoten"],
      fr: ["apa", "mla"],
      dk: ["apa"],
      es: ["apa"],
      it: ["apa"],
    }[this.domain];
  }

  sourceTypes() {
    return this.segment({
      com: "cite",
      "co.uk": "cite",
      nl: "citeer",
      de: "zitieren",
      at: "zitieren",
      ch: "zitieren",
      fr: "citer",
      dk: "cite",
      es: "citar",
      it: "cite",
    });
  }

  sourceType(sourceType: SourceType) {
    return this.sourceTypes().segment(this.getLocalizedStringFromSourceType(sourceType));
  }

  sourceTypeLandingPages() {
    return SourceTypes;
  }

  folders() {
    return this.foldersIndex();
  }

  folder(folderId?: ID) {
    return this.foldersIndex().folderId(folderId);
  }

  lists(folderId?: ID) {
    return this.foldersIndex().folderId(folderId).listsIndex();
  }

  list(folderId?: ID, listId?: ID) {
    return this.foldersIndex().folderId(folderId).listsIndex().listId(listId);
  }

  sources(folderId?: ID, listId?: ID) {
    return this.foldersIndex().folderId(folderId).listsIndex().listId(listId).sourcesIndex();
  }

  source(folderId?: ID, listId?: ID, sourceId?: ID) {
    return this.foldersIndex().folderId(folderId).listsIndex().listId(listId).sourcesIndex().sourceId(sourceId);
  }

  extensionUninstalled() {
    return this.segment("extension-uninstalled");
  }

  create() {
    return this.segment({
      com: "create",
      "co.uk": "create",
      nl: "creeer",
      de: "erstellen",
      at: "erstellen",
      ch: "erstellen",
      fr: "creer",
      dk: "create",
      es: "crear",
      it: "create",
    });
  }

  edit() {
    return this.segment({
      com: "edit",
      "co.uk": "edit",
      nl: "bewerk",
      de: "anpassen",
      at: "anpassen",
      ch: "anpassen",
      fr: "modifier",
      dk: "edit",
      es: "editar",
      it: "edit",
    });
  }

  getRoute() {
    return this.toString(false);
  }

  getPath() {
    const params = new URLSearchParams(this.queryParams).toString();
    return `${this.toString(true)}${(params && `?${params}`) || ""}`;
  }

  getHref(env: ScribbrEnv) {
    return `${getScribbrHost(this.domain, env)}${this.getPath()}`;
  }

  withQueryParam<K extends keyof QueryParams>(key: K, value: Exclude<QueryParams[K], undefined>) {
    const encoded = queryParamEncoders[key].encode(value);
    const newRoute = new RouteBuilder(this.domain);
    newRoute.segments = this.segments;
    newRoute.queryParams = { ...this.queryParams, [key]: encoded };
    return newRoute;
  }

  getQueryParam<K extends keyof QueryParams>(
    key: K,
    searchParams: URLSearchParams,
  ): Exclude<QueryParams[K], undefined> | null {
    const encoded = searchParams.get(key);
    if (encoded == null) {
      return null;
    }

    return queryParamEncoders[key].decode(encoded);
  }

  getLocalizedStringFromSourceType(sourceType: SourceType): string {
    return localizedSourceTypes[this.domain]?.[sourceType] || sourceType;
  }

  getSourceTypeFromLocalizedString(value: string): SourceType | null {
    const [sourceType] = Object.entries(localizedSourceTypes[this.domain] || {}).find(
      ([, text]) => text === value,
    ) || [value];
    if (isSourceType(sourceType)) {
      return sourceType;
    }

    return null;
  }

  private foldersIndex() {
    return this.segment({
      com: "folders",
      "co.uk": "folders",
      nl: "mappen",
      de: "ordnern",
      at: "ordnern",
      ch: "ordnern",
      fr: "dossier",
      dk: "folders",
      es: "folders",
      it: "folders",
    });
  }

  private listsIndex() {
    return this.segment({
      com: "lists",
      "co.uk": "lists",
      nl: "lijsten",
      de: "listen",
      at: "listen",
      ch: "listen",
      fr: "listes",
      dk: "lists",
      es: "lists",
      it: "lists",
    });
  }

  private sourcesIndex() {
    return this.segment({
      com: "sources",
      "co.uk": "sources",
      nl: "bronnen",
      de: "quellen",
      at: "quellen",
      ch: "quellen",
      fr: "references",
      dk: "sources",
      es: "fuentes",
      it: "sources",
    });
  }

  private folderId(folderId?: ID) {
    return this.param([":folderId", folderId && shortenID(folderId)]);
  }

  private listId(listId?: ID) {
    return this.param([":listId", listId && shortenID(listId)]);
  }

  private sourceId(sourceId?: ID) {
    return this.param([":sourceId", sourceId && shortenID(sourceId)]);
  }

  private toString(interpolateParams: boolean) {
    const path = this.segments
      .map((segment) =>
        Array.isArray(segment) ? (interpolateParams ? segment[1] || "undefined" : segment[0]) : segment,
      )
      .join("/");

    return `/${path.length > 0 ? `${path}/` : ""}`;
  }

  private segment(segment: string | Record<Domain, Segment>) {
    const newRoute = new RouteBuilder(this.domain);
    newRoute.segments = [...this.segments, typeof segment === "string" ? segment : segment[this.domain]];
    newRoute.queryParams = this.queryParams;
    return newRoute;
  }

  private param(p: [param: string, value: string | undefined]) {
    const newRoute = new RouteBuilder(this.domain);
    newRoute.segments = [...this.segments, p];
    newRoute.queryParams = this.queryParams;
    return newRoute;
  }
}

export function Routes(domain: Domain) {
  return new RouteBuilder(domain);
}

