import { InvalidResponseError, NetworkError, jsonDateReviver } from "@cgs/utils";

const _fetch = async (path: string, options?: RequestInit): ReturnType<typeof fetch> => {
  try {
    return await fetch(path, options);
  } catch (e) {
    if (e instanceof Error && e.name === "AbortError") {
      throw e;
    }

    throw new NetworkError(e);
  }
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
async function fetchJson(url: string, options?: RequestInit): Promise<any> {
  const response = await _fetch(url, options);
  const jsonResponse = JSON.parse((await response.text()) ?? null, jsonDateReviver);
  if (!response.ok) {
    const error = new InvalidResponseError(response.status, url);
    error.message = jsonResponse.error;
    throw error;
  }
  return jsonResponse;
}

export { _fetch as fetch, fetchJson };
