import {
  Source,
  List as ListType,
  UserInfo,
  BibliographyEntry,
  SummarizerRatio,
  SummarizerMode,
  AmplitudeEvent,
  defaultCitationStyle,
  Locale,
  CitationResponse,
  TextCase,
  ListSettings,
} from "@cgs/types";
import { CitationStyle } from "@cgs/citation-engine/types";
import { z } from "zod";
import { GoogleDocs } from "../google";
import { Variant } from "@cgs/analytics";

export type CiteMessage = {
  type: "cite";
  citationStyle: CitationStyle;
};

export type RequestDocumentMessage = {
  type: "requestHtmlOrPdfDocument";
};

export type HtmlDocumentMessage = {
  type: "htmlDocument";
  html: string;
  url: string;
};

export type PdfDocumentMessage = {
  type: "pdfDocument";
  url: string;
  contents: string | undefined;
};

export type RequestDocumentContentMessage = {
  type: "requestDocumentContent";
};

export type DocumentContentMessage = {
  type: "documentContent";
  documentContent?: DocumentContent;
};

export type CiteResponseMessage = {
  type: "citeResponse";
  source: Source;
};

export type FoldersMessage = {
  type: "folders";
  folders: Array<Folder> | undefined;
};

export type AddToListMessage = {
  type: "addToList";
  source: Source;
  list?: List;
};

export type AddSourceResponseMessage = {
  type: "addSourceResponse";
  ok: boolean;
};

export type ErrorMessage = {
  type: "error";
  errorMessage?: string;
  errorType?:
    | "NetworkError"
    | "MaintenanceModeError"
    | "ContentTooLargeError"
    | "InvalidResponseError"
    | "ExtractSourceError"
    | "ContentScriptNotAvailableError"
    | "GoogleUnauthorizedError"
    | "GoogleForbiddenError";
};

export type LogEventMessage = {
  type: "logEvent";
  event: AmplitudeEvent;
};

export type OpenAlexWorks = "relatedWorks" | "referencedWorks" | "citedBy";

export type OtherWorksMessage = {
  type: "otherWorks";
  doi: string;
  relation: OpenAlexWorks;
};

export type OtherWorksResponseMessage = {
  type: "otherWorksResponse";
  sources: Array<Source>;
};

export type OtherWorksErrorMessage = {
  type: "otherWorksError";
  error: string;
};

export type SummaryMessage = {
  type: "summarize";
  doi?: string;
  mode: SummarizerMode;
};

export type SummaryResponseMessage = {
  type: "summaryResponse";
  summary: string | Array<string>;
  mode: SummarizerMode;
};

export type SummaryErrorMessage = {
  type: "summaryError";
  error: string;
};

export type UserInfoMessage = {
  type: "userInfo";
  userInfo?: UserInfo;
};

export type FetchUserInfoMessage = {
  type: "fetchUserInfo";
};

export type FetchFoldersMessage = {
  type: "fetchFolders";
};

export type TextCaseMessage = {
  type: "textCase";
  params: {
    input: string;
    locale: Locale;
    textCase: TextCase;
    signal?: AbortSignal;
  };
};

export type TextCaseResponse = {
  type: "textCaseResponse";
  output: string;
};

export type CitationRequestMessage = {
  type: "citationRequest";
  source: Source;
  destination: "page" | "history";
  citationStyle: CitationStyle;
};

export type CitationResponseMessage = Omit<CitationRequestMessage, "type"> &
  CitationResponse & {
    type: "citationResponse";
  };

export type UpdateContentScriptsMessage = {
  type: "updateContentScripts";
};

export type AddToDocsMessage = {
  type: "addToDocs";
  list: List;
  docsId: string;
  token: string;
};

export type FetchGoogleDocMessage = {
  type: "fetchGoogleDoc";
  docsId: string;
  token: string;
};

export type GoogleDocMessage = {
  type: "googleDoc";
  document: GoogleDocs.Document;
};

export type GoogleDocsTokenMessage = {
  type: "googleDocsToken";
  token: string | undefined;
};

export type AmplitudeVariantRequestMessage = {
  type: "fetchAmplitudeVariant";
  key: string;
};

export type AmplitudeVariantResponseMessage = {
  type: "amplitudeVariant";
  variant?: Variant;
};

export type Message =
  | CiteMessage
  | CiteResponseMessage
  | FoldersMessage
  | AddToListMessage
  | AddSourceResponseMessage
  | ErrorMessage
  | UserInfoMessage
  | SummaryMessage
  | SummaryResponseMessage
  | SummaryErrorMessage
  | LogEventMessage
  | RequestDocumentMessage
  | HtmlDocumentMessage
  | PdfDocumentMessage
  | RequestDocumentContentMessage
  | DocumentContentMessage
  | UpdateContentScriptsMessage
  | CitationRequestMessage
  | CitationResponseMessage
  | FetchUserInfoMessage
  | FetchFoldersMessage
  | OtherWorksMessage
  | OtherWorksResponseMessage
  | OtherWorksErrorMessage
  | TextCaseMessage
  | TextCaseResponse
  | AddToDocsMessage
  | FetchGoogleDocMessage
  | GoogleDocMessage
  | GoogleDocsTokenMessage
  | AmplitudeVariantRequestMessage
  | AmplitudeVariantResponseMessage;

export type Settings = {
  citationStyle: CitationStyle;
  selectedTab: Tab;
  summarizerMode: SummarizerMode;
  summarizerRatio: SummarizerRatio;
  hideBadgeForAllOrigins?: boolean;
  hiddenBadgeOrigins: Array<string>;
  googleDocsToken?: string;
  selectedList?: List;
};

export const defaultSettings: Settings = {
  citationStyle: defaultCitationStyle,
  selectedTab: "cite",
  summarizerMode: "extractive",
  summarizerRatio: "medium",
  hiddenBadgeOrigins: [],
};

export const tabs = ["cite", "summarize", "otherWorks"] as const;
export type Tab = (typeof tabs)[number];

export type Route = { page: "home"; props?: null } | { page: "settings"; props?: null };

export type Navigate = (route: Route) => void;

export type FoldersResponse = {
  folders: Array<Folder>;
};

export type ListResponse = {
  list: Readonly<{
    id: ID;
    settings: ListSettings;
    createdAt: Date;
    bibliography: Array<BibliographyEntry>;
    generatedBibliography?: boolean;
  }>;
};

export type Folder = {
  id: ID;
  name: string;
  isRoot: boolean;
  lists: Array<List>;
};

export type List = ListType & {
  folderId: ID;
  folderName: string;
  link: string;
  updatedAt: string;
  sourceCount: number;
};

export type ReadabilityArticle = {
  title: string;
  content: string;
  textContent: string;
  length: number;
  excerpt: string;
  byline: string;
  dir: string;
  siteName: string;
  lang: string;
};

export type SummarizerResponse = {
  message: string;
  traceID: string;
  data: {
    summary: string;
    sent: string;
    modelId: string;
    out: string;
  };
  output_keywords: Array<string>;
  keywords: Array<string>;
};

export type DocumentContent = {
  content: string;
  title: string;
};

export const BadgePopupStates = ["closed", "open", "copied", "error", "loading"] as const;
export type BadgePopupState = (typeof BadgePopupStates)[number];

export const privacyPolicyUrl: Record<Locale, string> = {
  "en-US": "https://www.scribbr.com/legal/privacy-policy/",
  "nl-NL": "https://www.scribbr.nl/legal/veiligheid-en-privacy/",
  "de-DE": "https://www.scribbr.de/legal/datenschutzrichtlinie/",
  "fr-FR": "https://www.scribbr.fr/juridique/politique-de-confidentialite/",
  "es-ES": "https://www.scribbr.es/legal/politica-de-privacidad/",
};

export type MessageOrigin = "popup" | "badge" | "settings";

type HistoryEntryV1 = {
  id: string;
  source: Source;
  timestamp: number;
  isEditedSource: boolean;
  version: "1";
};

export type HistoryEntry = HistoryEntryV1;

export const HistoryEntryV1Schema = z.object({
  id: z.string(),
  source: z.object({}), // TODO - hoist validation from app to a new workspace
  timestamp: z.number(),
  isEditedSource: z.boolean().optional(),
  version: z.literal("1"),
});

export const HistoryEntrySchema = HistoryEntryV1Schema;

export type Summary = {
  isLoading: boolean;
  response: {
    [key in SummarizerMode]: string | Array<string> | undefined;
  };
  summaryError: string | undefined;
};
