import { v4 } from "uuid";

export const UUID_RGX = /^[A-Za-z0-9]{8}-[A-Za-z0-9]{4}-4[A-Za-z0-9]{3}-[A-Za-z0-9]{4}-[A-Za-z0-9]{12}$/;

const HEX = "0123456789abcdef";
const BASE58 = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

export function newID(): ID {
  return v4() as ID;
}

export function isID(value: unknown): value is ID {
  return typeof value === "string" && value.match(UUID_RGX) != null;
}

export function isShortID(value: unknown): value is string {
  return typeof value === "string" ? isID(expandID(value)) : false;
}

// https://github.com/HarasimowiczKamil/any-base/blob/master/src/converter.js
function convertBaseToBase(srcAlphabet: string, dstAlphabet: string, number: string) {
  const fromBase = srcAlphabet.length;
  const toBase = dstAlphabet.length;
  let length = number.length;
  const numberMap = [];
  let result = "";

  for (let i = 0; i < length; i += 1) {
    numberMap.push(srcAlphabet.indexOf(number.charAt(i)));
  }

  let newLen, divide;
  do {
    newLen = 0;
    divide = 0;
    for (let i = 0; i < length; i += 1) {
      divide = divide * fromBase + (numberMap[i] || 0);
      if (divide >= toBase) {
        numberMap[newLen++] = parseInt((divide / toBase).toString(), 10);
        divide = divide % toBase;
      } else if (newLen > 0) {
        numberMap[newLen++] = 0;
      }
    }
    length = newLen;
    result = dstAlphabet.slice(divide, divide + 1).concat(result);
  } while (newLen !== 0);

  return result;
}

export function shortenID(id: ID): string {
  return convertBaseToBase(HEX, BASE58, id.toLowerCase().replace(/-/g, ""));
}

export function expandID(id: string): ID {
  const uuid = convertBaseToBase(BASE58, HEX, id).padStart(32, "0");

  const match = uuid.match(/(\w{8})(\w{4})(\w{4})(\w{4})(\w{12})/);

  return [match?.[1], match?.[2], match?.[3], match?.[4], match?.[5]].join("-") as ID;
}
