const env = (process.env.SCRIBBR_ENV || "dev") as ScribbrEnv;

const amplitudeClient = new AmplitudeClient("browser-extension", env, "com");

// set access level to allow content scripts to access session storage
chrome.storage.session.setAccessLevel({ accessLevel: "TRUSTED_AND_UNTRUSTED_CONTEXTS" });

chrome.storage.local.get("amplitudeDeviceId", ({ amplitudeDeviceId: storedDeviceId }) => {
  if (storedDeviceId) {
    amplitudeClient.setDeviceId(storedDeviceId);
  } else {
    const newDeviceId = amplitudeClient.getDeviceId();
    if (newDeviceId) {
      chrome.storage.local.set({ amplitudeDeviceId: newDeviceId });
    }
  }
});

const VERSION = chrome.runtime.getManifest().version;

async function injectContentScripts(tabId?: number) {
  // inject content scripts into open tabs after install/upgrade
  for (const cs of chrome.runtime.getManifest().content_scripts || []) {
    if (!cs.js || !cs.matches) {
      continue;
    }

    const tabs = await chrome.tabs.query({ url: cs.matches });

    for (const tab of tabs) {
      if (tabId && tab.id !== tabId) {
        continue;
      }

      if (tab.id != null) {
        try {
          await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            files: cs.js,
          });
        } catch (e) {
          // ignore, some sites prevent injecting scripts, chrome webstore etc
        }
      }
    }
  }
}

chrome.runtime.onInstalled.addListener(async (details) => {
  if (process.env.NODE_ENV === "development") {
    await chrome.action.setBadgeText({ text: "DEV" });
  }

  await injectContentScripts();
  if (details.reason === chrome.runtime.OnInstalledReason.INSTALL) {
    amplitudeClient.logEvent({
      name: "Citation Generator Browser Extension Installed",
      data: {
        version_number: VERSION,
      },
    });
  }
  if (details.reason === chrome.runtime.OnInstalledReason.UPDATE) {
    amplitudeClient.logEvent({
      name: "Citation Generator Browser Extension Updated",
      data: {
        version_number: VERSION,
      },
    });
  }
});

chrome.runtime.setUninstallURL(
  env === "production" && process.env.NODE_ENV === "production"
    ? Routes("com").extensionUninstalled().withQueryParam("version", VERSION).getHref(env)
    : "",
);

chrome.tabs.onUpdated.addListener(async (tabId, changeInfo) => {
  if (changeInfo.status === "complete") {
    // clear tab session storage on page load
    chrome.storage.session.remove(tabId.toString());
  }
});

chrome.tabs.onRemoved.addListener((tabId) => {
  chrome.storage.session.remove(tabId.toString());
});

chrome.runtime.onMessage.addListener((message: Message, sender, sendResponse) => {
  const handleError = (e: Error) => {
    Sentry.captureException(e);
  };

  switch (message.type) {
    case "logEvent":
      return amplitudeClient.logEvent(message.event);
    case "updateContentScripts":
      return injectContentScripts().catch(handleError);
    case "fetchUserInfo":
      return handleUserInfoMessage().catch(handleError);
    case "addToDocs":
    case "textCase":
    case "cite":
    case "addToList":
    case "summarize":
    case "otherWorks":
    case "citationRequest":
    case "fetchAmplitudeVariant":
    case "fetchGoogleDoc": {
      handleMessagesExpectingResponse(message, sender.tab?.id)
        .then((resp) => {
          if (resp) {
            sendResponse(resp);
          }
        })
        .catch(handleError);
      return true;
    }
  }
  return void 0;
});

const handleMessagesExpectingResponse = async (message: Message, tabId?: number | null) => {
  switch (message.type) {
    case "cite":
      return await handleCiteMessage(message, tabId);
    case "addToList":
      return await handleAddToListMessage(message, tabId);
    case "summarize":
      return await handleSummarizeMessage(message, tabId);
    case "citationRequest":
      return await handleChangeCitationStyleRequest(message);
    case "otherWorks":
      return await handleOtherWorksMessage(message);
    case "textCase":
      return await handleTextCaseMessage(message);
    case "fetchGoogleDoc":
      return await handleFetchGoogleDocMessage(message);
    case "addToDocs":
      return handleAddToDocsMessage(message);
    case "fetchAmplitudeVariant": {
      const experimentDeploymentKey = amplitudeClient.getExperimentDeploymentKey();

      const experimentClient = experimentDeploymentKey
        ? Experiment.initializeWithAmplitudeAnalytics(experimentDeploymentKey, {
            automaticExposureTracking: true,
          })
        : undefined;

      if (experimentClient) {
        await experimentClient.fetch({
          user_id: amplitudeClient.getUserId(),
          device_id: amplitudeClient.getDeviceId(),
        });
      }

      const variant = experimentClient?.variant(message.key);

      return {
        type: "amplitudeVariant",
        variant,
      };
    }
  }
  return void 0;
};

chrome.runtime.onMessageExternal.addListener((message, _sender, sendResponse) => {
  if (message === "ping") {
    sendResponse("pong");
  }
});

type TabSession = {
  tabId: number;
  source?: Source;
  citation?: Citation;
  bibEntry?: BibliographyEntry;
  content?: string;
  title?: string;
  summary?: Array<SummaryResponseMessage>;
  options?: CitationStyleOptions;
  citationStyle?: CitationStyle;
};

async function getTabSession(id?: number | null): Promise<TabSession | undefined> {
  let tabId = id;
  if (!tabId) {
    const tab = await getActiveTab();
    tabId = tab.id;
  }

  const session = await chrome.storage.session.get();

  if (!(tabId && session && session[tabId] && session[tabId].source)) {
    return;
  }

  return {
    tabId,
    source: session[tabId].source,
    citation: session[tabId].citation,
    content: session[tabId].content,
    title: session[tabId].title,
    bibEntry: session[tabId].bibEntry,
    options: session[tabId].options,
    citationStyle: session[tabId].citationStyle,
    summary: session[tabId].summary,
  };
}

async function setTabSession(tabId: number, session: Partial<TabSession>) {
  const previousSession = await getTabSession(tabId);
  await chrome.storage.session.set({
    [tabId]: { ...previousSession, ...session },
  });
}

async function handleCiteMessage(
  message: CiteMessage,
  tabId?: number | null,
): Promise<CiteResponseMessage | ErrorMessage | undefined> {
  const tab = await getActiveTab();

  amplitudeClient.logEvent({
    name: "Citation Generator Browser Extension Opened",
    data: {
      extension_language: "en-US",
      citation_language: "en-US",
      citation_style: message.citationStyle[0],
      citation_style_variation: message.citationStyle[1],
      url: tab.url,
    },
  });

  const session = await getTabSession(tabId);
  const history = await fetchHistory();

  // Check if citation exists in session
  if (doesCitationExistInTabSession(message, session)) {
    const source = history.find((entry) => entry.id === tab.url)?.source || session.source;

    // Update source timestamp in history
    await upsertSourceToHistory(source, tab.url);
    return { type: "citeResponse", source };
  }

  try {
    const startTime = Date.now();

    const content: HtmlDocumentMessage | PdfDocumentMessage = await sendMessageToTab(tab.id, {
      type: "requestHtmlOrPdfDocument",
    });

    const experimentDeploymentKey = amplitudeClient.getExperimentDeploymentKey();

    const experimentClient = experimentDeploymentKey
      ? Experiment.initializeWithAmplitudeAnalytics(experimentDeploymentKey, {
          automaticExposureTracking: true,
        })
      : undefined;

    if (experimentClient) {
      await experimentClient.fetch({
        user_id: amplitudeClient.getUserId(),
        device_id: amplitudeClient.getDeviceId(),
      });
    }

    const autocitePdfEnabled = experimentClient?.variant("enable-pdf-autocite", { value: "off" }).value === "on";

    const autociteRequest: AutociteRequest =
      content.type === "htmlDocument"
        ? { ...content, type: "html-document" }
        : { ...content, type: "pdf", isUploaded: false, featureFlags: { autocitePdfEnabled } };

    let source = history.find((entry) => entry.id === tab.url && entry.isEditedSource)?.source;

    // if the source is not in the history, fetch it from autocite
    if (!source) {
      const autociteRes = await fetchAutocite(autociteRequest);

      if (autociteRes?.type !== "sources") {
        throw new ExtractSourceError();
      }
      source = autociteRes.data.sources[0];

      if (!source || !source.data.url) {
        throw new ExtractSourceError();
      }
      const endTime = Date.now();
      amplitudeClient.logEvent({
        name: "Citation Generator Autocite Searched",
        data: {
          query: source.data.url,
          hostname: getHostname(content.url),
          search_successful: true,
          response_time: endTime - startTime,
        },
      });
    }

    await setTabSession(tab.id, {
      tabId: tab.id,
      source,
    });

    // add source to the history
    await upsertSourceToHistory(source, tab.url);

    return { type: "citeResponse", source };
  } catch (e) {
    if (isAbortError(e)) {
      // ignore abort errors
      return undefined;
    } else {
      assertIsError(e);
      const errorType = (() => {
        switch (true) {
          case e instanceof InvalidResponseError: {
            switch ((e as InvalidResponseError).statusCode) {
              case 413:
                return "ContentTooLargeError";
              default:
                return "InvalidResponseError";
            }
          }
          case e instanceof ExtractSourceError:
            return "ExtractSourceError";
          case e instanceof MaintenanceModeError:
            return "MaintenanceModeError";
          case e instanceof NetworkError:
            return "NetworkError";
          case e instanceof ContentScriptNotAvailableError:
            return "ContentScriptNotAvailableError";
          default:
            return undefined;
        }
      })();
      return {
        type: "error",
        errorType,
        errorMessage: e.message,
      };
    }
  }
}

async function handleChangeCitationStyleRequest({
  citationStyle,
  source,
  destination,
}: CitationRequestMessage): Promise<CitationResponseMessage | ErrorMessage | undefined> {
  try {
    const citationResponse = await fetchCitation(citationStyle, source);
    const tab = await getActiveTab();

    const response = {
      type: "citationResponse",
      citationStyle,
      source,
      destination,
      ...citationResponse,
    } satisfies CitationResponseMessage;

    amplitudeClient.logEvent({
      name: "Citation Generator Source Cited",
      data: {
        source_type: source.data.type,
        citation_style: citationStyle[0],
        citation_style_variation: citationStyle[1],
        mode: "auto",
      },
    });

    setTabSession(tab.id, {
      citation: response.citation,
      bibEntry: response.bibEntry,
      options: response.options,
      citationStyle,
    });

    return response;
  } catch (e) {
    if (isAbortError(e)) {
      // ignore abort errors
      return undefined;
    } else {
      assertIsError(e);

      return {
        type: "error",
        errorType: e instanceof MaintenanceModeError ? "MaintenanceModeError" : "NetworkError",
        errorMessage: e.message,
      };
    }
  }
}

const mappedRelation = {
  citedBy: "cited-by",
  referencedWorks: "referenced",
  relatedWorks: "related",
} as const;

async function handleOtherWorksMessage(
  message: OtherWorksMessage,
): Promise<OtherWorksResponseMessage | OtherWorksErrorMessage> {
  try {
    const autociteRes = await fetchAutocite({
      type: "doi",
      doi: message.doi,
      relation: mappedRelation[message.relation],
    });
    if (autociteRes?.type !== "sources" || autociteRes.data.sources.length === 0) {
      throw new Error();
    } else {
      return {
        type: "otherWorksResponse",
        sources: autociteRes.data.sources,
      };
    }
  } catch (e) {
    return {
      type: "otherWorksError",
      error: "We could not find any other works for this source",
    };
  }
}

async function handleUserInfoMessage(): Promise<void> {
  const userInfo = await fetchMe();
  if (userInfo) {
    await chrome.storage.session.set({ userInfo });
    if (userInfo.scribbrId) {
      amplitudeClient.setUserId(userInfo.scribbrId.toString());
    }
    Sentry.setUser({ id: userInfo.id, level: userInfo.level });
    if (userInfo.level === UserLevel.REGISTERED) {
      const response = await fetchFolders();
      if (response) {
        await chrome.storage.session.set({ folders: response.folders });
      }
    }
  } else {
    // user logged out, clear userInfo and folders
    await chrome.storage.session.remove("userInfo");
    await chrome.storage.session.remove("folders");
  }
}

async function handleTextCaseMessage(message: TextCaseMessage): Promise<TextCaseResponse> {
  const { output } = await fetchTextCase(message.params);

  return {
    type: "textCaseResponse",
    output,
  };
}

async function getAbstract(doi: string): Promise<string | undefined> {
  const citationResponse = await fetchAutocite({ type: "abstract", doi });

  if (citationResponse?.type !== "abstract") {
    return undefined;
  }

  return citationResponse.data.abstract;
}

async function getDocumentContent(tabId: number): Promise<string | undefined> {
  const documentContent: DocumentContentMessage = await chrome.tabs.sendMessage(tabId, {
    type: "requestDocumentContent",
  });

  return documentContent?.documentContent?.content;
}

async function handleSummarizeMessage(message: SummaryMessage, tabId?: number | null) {
  const activeTabId = tabId || (await getActiveTab()).id;

  let response: Message;

  const contentToSummarize = message.doi ? await getAbstract(message.doi) : await getDocumentContent(activeTabId);

  if (contentToSummarize) {
    try {
      const summaryResponse = await fetchSummary(contentToSummarize, message.mode);
      const summary = await getSummaryContentByMode(summaryResponse, message.mode);
      response = {
        type: "summaryResponse",
        summary,
        mode: message.mode,
      };
    } catch (e) {
      response = {
        type: "summaryError",
        error: "Unable to summarize",
      };
    }
  } else {
    response = {
      type: "summaryError",
      error: "No content found to summarize",
    };
  }

  amplitudeClient.logEvent({
    name: "Citation Generator Source Summarized",
    data: {
      mode: message.mode,
    },
  });
  return response;
}

async function handleAddToListMessage(
  message: AddToListMessage,
  tabId?: number | null,
): Promise<AddSourceResponseMessage | ErrorMessage> {
  const session = await getTabSession(tabId);
  const addSource = message.list
    ? addSourceToList(message.source, message.list.folderId, message.list.id)
    : // TODO: Remove this once the issue is fixed in TypeScript
      // https://github.com/microsoft/TypeScript/issues/45149
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore
      addNewSource(message.source, session.citationStyle || defaultCitationStyle);

  const ok = await addSource;
  if (ok) {
    amplitudeClient.logEvent({
      name: "Citation Generator Browser Extension Source Added To List",
    });
  }
  return { type: "addSourceResponse", ok: !!ok };
}

function doesCitationExistInTabSession(
  message: CiteMessage,
  session?: TabSession,
): session is Required<TabSession> {
  if (!session) {
    return false;
  }
  return (
    !!session.source &&
    !!session.citation &&
    !!session.bibEntry &&
    !!session.options &&
    session.citationStyle?.join() === message.citationStyle.join()
  );
}

async function sendMessageToTab(tabId: number, message: Message) {
  try {
    return await chrome.tabs.sendMessage(tabId, message);
  } catch (e) {
    assertIsError(e);

    if (e.message === "Could not establish connection. Receiving end does not exist.") {
      throw new ContentScriptNotAvailableError();
    }

    throw e;
  }
}

async function handleAddToDocsMessage(message: AddToDocsMessage): Promise<GoogleDocMessage | ErrorMessage> {
  const googleDoc = await fetchDocument(message.docsId, message.token);
  const listResponse = await fetchList(message.list.folderId, message.list.id);

  const requests = makeBatchRequests(googleDoc, listResponse.list);

  if (requests.length > 0) {
    try {
      await batchUpdateDocument(googleDoc, message.token, requests);
    } catch (e) {
      return {
        type: "error",
        errorType: "InvalidResponseError",
        errorMessage: "Unable to add sources to Google Doc",
      };
    }
  }

  return handleFetchGoogleDocMessage({ type: "fetchGoogleDoc", docsId: message.docsId, token: message.token });
}

async function handleFetchGoogleDocMessage(
  message: FetchGoogleDocMessage,
): Promise<GoogleDocMessage | ErrorMessage> {
  try {
    const document = await fetchDocument(message.docsId, message.token);

    return { type: "googleDoc", document };
  } catch (e) {
    assertIsError(e);

    if (e instanceof GoogleUnauthorizedError) {
      await chrome.identity.removeCachedAuthToken({ token: message.token });
      return { type: "error", errorType: "GoogleUnauthorizedError", errorMessage: "Google unauthorized" };
    }

    if (e instanceof GoogleForbiddenError) {
      return { type: "error", errorType: "GoogleForbiddenError", errorMessage: "Google forbidden" };
    }

    return { type: "error", errorType: "NetworkError", errorMessage: "Unable to fetch Google Doc" };
  }
}

export {};
