import { object, string, tuple, array, number, parse } from "valibot";
import { UnreachableCaseError } from "./";
import { SummarizerMode } from "@cgs/types";

const abstractiveSummaryResponseSchema = object({
  message: string(),
  data: object({
    id: string(),
    out: string(),
  }),
});

const extractiveSummaryResponseSchema = object({
  message: string(),
  data: object({
    id: string(),
    out: tuple([array(string()), array(number())]),
  }),
});

export async function getSummaryContentByMode(
  summaryResponse: { out: string },
  mode: SummarizerMode,
): Promise<string | Array<string>> {
  switch (mode) {
    case "abstractive":
      return parse(abstractiveSummaryResponseSchema, summaryResponse).data.out;
    case "extractive":
      const [sentences, scores] = parse(extractiveSummaryResponseSchema, summaryResponse).data.out;
      return getHighestScoreSentences(sentences, scores);
    default:
      throw new UnreachableCaseError(mode);
  }
}

export function getHighestScoreSentences(sentences: Array<string>, scores: Array<number>): Array<string> {
  // return a max of 50% or 5 sentences with the highest scores
  const maxSentences = Math.min(Math.ceil(sentences.length / 2), 5);
  const highestScores = scores
    .map((score, index) => ({ score, index }))
    .sort((a, b) => b.score - a.score)
    .slice(0, maxSentences)
    .sort((a, b) => a.index - b.index);

  return sentences.filter((_, index) => highestScores.some(({ index: i }) => i === index));
}
