import { Domain, Locale } from "@cgs/types";
import { domainLocales, parseUrl } from "@cgs/utils";
import { Token } from "./types";

export function chunk<T>(items: T[], chunkSize: number): T[][] {
  return items.reduce(
    (previousValue, _currentValue, currentIndex, array) =>
      !(currentIndex % chunkSize)
        ? previousValue.concat([array.slice(currentIndex, currentIndex + chunkSize)])
        : previousValue,
    [] as T[][],
  );
}

export function getLocaleForDomain(domain: Domain) {
  return domainLocales[domain];
}

export function getCountryCodeFromLocale(locale: Locale): string {
  return (locale as string).split("-")[1] as string;
}

export function getHostname(url: string): string | undefined {
  const parsed = parseUrl(url) || parseUrl(`https://${url}`);
  return parsed?.hostname;
}

// Copied and modified from https://www.oreilly.com/library/view/regular-expressions-cookbook/9780596802837/ch04s13.html
export function isIsbn(s: string) {
  const ISBN_REGEXP = new RegExp(
    "^(?:ISBN(?:-1[03])?:? )?(?=[-0-9 ]{17}$|[-0-9X ]{13}$|[0-9X]{10}$)(?:97[89][- ]?)?[0-9]{1,5}[- ]?(?:[0-9]+[- ]?){2}[0-9X]$",
  );

  if (!ISBN_REGEXP.test(s)) {
    return false;
  }

  // Remove non ISBN digits, then split into an array
  const chars = s.replace(/[^0-9X]/g, "").split("");
  // Remove the final ISBN digit from `chars`, and assign it to `last`
  const last = chars.pop();
  let sum = 0;
  let digit = 10;
  let check: string;

  if (chars.length == 9) {
    // Compute the ISBN-10 check digit
    chars.forEach((char) => {
      sum += digit * parseInt(char, 10);
      digit -= 1;
    });
    check = String(11 - (sum % 11));
    if (check == "10") {
      check = "X";
    } else if (check == "11") {
      check = "0";
    }
  } else {
    // Compute the ISBN-13 check digit
    chars.forEach((char, i) => {
      sum += ((i % 2) * 2 + 1) * parseInt(char, 10);
    });
    check = String(10 - (sum % 10));
    if (check == "10") {
      check = "0";
    }
  }

  return check === last;
}

export const getPublicBasePath = () => {
  return `${getBasePath()}/public`;
};

export const getBasePath = () => {
  return process.env.PUBLIC_PATH !== undefined
    ? `${process.env.PUBLIC_PATH}${process.env.BASE_PATH}`
    : `${process.env.BASE_PATH}`;
};

export function getDevToken(): Token {
  return {
    iat: Date.now() / 1000,
    exp: Date.now() / 1000 + 30 * 24 * 60 * 60,
    roles: [],
    username: "dev+loper@scribbr.nl",
    links: {},
    id: "dev-loper",
    name: {
      first: "Dev",
      infix: "e",
      last: "Loper",
    },
    phoneNumber: null,
    hasMarketingConsent: true,
    appName: "dev",
  };
}

export function tokenExpiresIn(token: Token, margin: number) {
  return token.exp * 1000 - margin <= Date.now();
}

export const escapeRegExp = (text: string): string => text.replace(/[\\^$.*+?()[\]{}|]/g, "\\$&");

export function unwrapFirstItem<T>(arr: Array<T> | T): T | undefined {
  return ([] as Array<T>).concat(arr)[0];
}

export function wrapArray<T>(arr: Array<T> | T): Array<T> {
  return ([] as Array<T>).concat(arr);
}
