import { AutociteEvent, AutociteRequest, CitationResponse, Source, SummarizerMode, UserInfo } from "@cgs/types";
import { isAbortError, newID } from "@cgs/utils";
import { FoldersResponse, ListResponse, TextCaseMessage } from "../common/types";
import { CitationStyle } from "@cgs/citation-engine/types";
import { Sentry } from "../common/sentry";
import { autocite } from "@cgs/autocite-component";
import { MaintenanceModeError, NetworkError, isMaintenanceModeError } from "../common/errors";

const baseUrl = process.env.API_BASE_PATH || "http://localhost:4000";

type FetchOptions = Parameters<typeof fetch>[1];

async function validateResponse(res: Response) {
  switch (true) {
    case res.status === 503:
      throw new MaintenanceModeError();
      break;
    case !res.ok:
      const result = await res.json();
      throw new NetworkError(result.error);
      break;
  }

  return res;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
async function parseResponse(res: Response): Promise<any> {
  const contentType = res.headers.get("Content-Type") || "application/octet-stream";

  switch (true) {
    case contentType.includes("application/json"):
      return res.json();
    case contentType.includes("application/pdf"):
      return res.blob();
    case contentType.includes("text/plain"):
      return res.text();
    default:
      return res;
  }
}

export async function fetchWrapper(path: string, options?: FetchOptions) {
  const method = options?.method || "GET";
  const defaultHeaders = { Accept: "application/json", "Content-Type": "application/json" };
  const defaultOptions: FetchOptions = { credentials: "include" };

  try {
    return fetch(`${baseUrl}${path}`, {
      headers: { ...defaultHeaders, ...options?.headers },
      ...options,
      ...defaultOptions,
      method,
      credentials: "include",
    })
      .then(validateResponse)
      .then(parseResponse);
  } catch (e) {
    if (isAbortError(e) || isMaintenanceModeError(e)) {
      // ignore
    } else {
      Sentry.captureException(e);
      throw e;
    }
  }
}

export async function fetchCitation(
  citationStyle: CitationStyle,
  source: Source,
  signal?: AbortSignal,
): Promise<CitationResponse> {
  const response: unknown = await fetchWrapper("/citation-generator-suite/api/v1/external/citation", {
    method: "post",
    signal,
    body: JSON.stringify({
      citationStyle,
      locale: "en-US",
      source,
    }),
  });

  return response as CitationResponse;
}

export async function fetchFolders(signal?: AbortSignal): Promise<FoldersResponse> {
  const response: unknown = await fetchWrapper("/citation-generator-suite/api/v1/external/folders", {
    signal,
  });

  return response as FoldersResponse;
}

export async function fetchList(folderId: ID, listId: ID, signal?: AbortSignal) {
  const response: unknown = await fetchWrapper(
    `/citation-generator-suite/api/v1/external/folders/${folderId}/lists/${listId}`,
    {
      signal,
    },
  );

  return response as ListResponse;
}

export async function fetchMe(signal?: AbortSignal): Promise<UserInfo> {
  const response: unknown = await fetchWrapper("/citation-generator-suite/api/v1/external/me", {
    signal,
  });

  return response as UserInfo;
}

export async function fetchSummary(text: string, mode: SummarizerMode, signal?: AbortSignal) {
  return fetchWrapper("/citation-generator-suite/com/api/v1/external/summarize", {
    method: "POST",
    signal,
    body: JSON.stringify({
      text,
      mode,
      ratio: "short",
    }),
  });
}

export async function addNewSource(source: Source, citationStyle: CitationStyle, signal?: AbortSignal) {
  return fetchWrapper("/citation-generator-suite/com/api/v1/external/new/source", {
    method: "post",
    signal,
    body: JSON.stringify({
      source,
      citationStyle,
      listId: newID(),
      locale: "en-US",
      font: "Times New Roman",
      fontSize: 12,
    }),
  });
}

export async function addSourceToList(source: Source, folderId: ID, listId: ID, signal?: AbortSignal) {
  return fetchWrapper(`/citation-generator-suite/com/api/v1/folders/${folderId}/lists/${listId}/sources`, {
    method: "post",
    signal,
    body: JSON.stringify({
      source: {
        ...source,
        id: newID(),
      },
    }),
  });
}

export async function fetchAutocite(request: AutociteRequest): Promise<AutociteEvent> {
  try {
    const response = await autocite(request);

    switch (response.type) {
      case "sources":
      case "abstract":
        return response;
      case "failed":
      case "forbidden":
      case "timeout":
      case "external_server_error":
      case "invalid_resource":
      default:
        throw new Error(response.data as string);
    }
  } catch (e) {
    if (isAbortError(e) || isMaintenanceModeError(e)) {
      return Promise.resolve({ type: "timeout", data: "Autocite request timed out" });
    } else {
      Sentry.captureException(e);

      throw e;
    }
  }
}

export async function fetchTextCase({ input, locale, textCase, signal }: TextCaseMessage["params"]) {
  return fetchWrapper("/citation-generator-suite/api/v1/external/text-case", {
    method: "post",
    signal,
    body: JSON.stringify({
      text: input,
      locale,
      textCase,
    }),
  }) as Promise<{
    output: string;
  }>;
}
