import { AmplitudeEvent, Domain, ScribbrEnv } from "@cgs/types";
import amplitude, { AmplitudeClient as Client } from "amplitude-js";
import { getKeysForInstance } from "./config";

export class AmplitudeClient {
  protected client: Client;
  protected readonly apiKey?: string;
  protected readonly experimentDeploymentKey?: string;

  constructor(
    protected readonly app: string,
    scribbrEnv: ScribbrEnv,
    domain: Domain,
  ) {
    const [apiKey, experimentDeploymentKey] = getKeysForInstance(scribbrEnv, domain);
    this.experimentDeploymentKey = experimentDeploymentKey;
    this.client = amplitude.getInstance();
    if (apiKey) {
      this.apiKey = apiKey;
      this.client.init(apiKey);
    }
  }

  getExperimentDeploymentKey() {
    return this.experimentDeploymentKey;
  }

  private scribbrToUserId(scribbrId?: string) {
    return `${scribbrId}`.padStart(5, "0");
  }

  setUserId(userId: string) {
    this.client.setUserId(this.scribbrToUserId(userId));
  }

  getUserId(): string | undefined {
    return this.client.getUserId() ?? undefined;
  }

  setDeviceId(deviceId: string) {
    this.client.setDeviceId(deviceId);
  }

  getDeviceId(): string | undefined {
    return this.client.getDeviceId() ?? undefined;
  }

  getIdentify() {
    if (typeof window === "undefined") {
      throw new Error("Cannot call getIdentify() on server");
    }
    return new amplitude.Identify();
  }

  setIdentify(identify: amplitude.Identify) {
    if (typeof window === "undefined") {
      throw new Error("Cannot call setIdentify() on server");
    }
    amplitude.identify(identify);
  }

  isNewSession() {
    return this.client.isNewSession();
  }

  logEvent(event: AmplitudeEvent) {
    if (this.apiKey) {
      const data = "data" in event ? event.data : null;
      this.client.logEvent(event.name, { ...data, app: this.app });
    }
  }
}
