import { UnverifiedCitationStyle, UnverifiedCitationStyleIDs } from "../types";
import { UnverifiedStylesTitles } from "./unverified-titles";

export function getUnverifiedCitationStyleTitle(style: UnverifiedCitationStyle): string {
  const [styleId] = style;

  const index = UnverifiedCitationStyleIDs.indexOf(styleId);
  const title = UnverifiedStylesTitles[index];
  if (!title) {
    return styleId;
  }

  return decodeXmlEntities(title);
}

function decodeXmlEntities(text: string): string {
  return text
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&#(\d+);/g, (_match, dec) => String.fromCharCode(dec));
}
