export class UnreachableCaseError extends Error {
  constructor(value: never) {
    super(`Unreachable case: ${value}`);
  }
}

export class TraceableError extends Error {
  public cause?: Error;

  constructor(message: string, cause?: unknown) {
    super(message);
    this.name = new.target.name;
    Object.setPrototypeOf(this, new.target.prototype);
    if (typeof Error.captureStackTrace === "function") {
      Error.captureStackTrace(this, new.target);
    }
    if (cause && cause instanceof Error) {
      this.cause = cause;
      let causeMessage = `${cause.name}: ${cause.message}`;
      if (cause.stack?.startsWith(causeMessage)) {
        causeMessage = cause.stack;
      } else {
        causeMessage = `${causeMessage} ${cause.stack}`;
      }
      this.stack += `\nCaused by: ${causeMessage}\n`;
    }
  }

  get root(): Error {
    let root: Error = this; // eslint-disable-line @typescript-eslint/no-this-alias
    while (root != null && root instanceof TraceableError && root.cause != null) {
      root = root.cause;
    }
    return root;
  }
}

export function assertIsError(error: unknown): asserts error is Error {
  if (!(error instanceof Error)) {
    throw error;
  }
}

export function isAbortError(error: unknown): error is Error {
  return (
    error instanceof AbortError ||
    (typeof error === "object" && error !== null && "name" in error && error.name === "AbortError")
  );
}

export function assertNotAborted(signal: AbortSignal | undefined) {
  if (signal == null) {
    return;
  }

  if (signal.aborted) {
    throw new AbortError();
  }
}

export class AbortError extends TraceableError {
  constructor() {
    super("Operation was aborted");
  }
}

export class ExtractSourceError extends TraceableError {
  constructor(cause?: unknown) {
    super("Failed to extract source", cause);
  }
}

export class FetchError extends TraceableError {}

export class FetchTimeoutError extends FetchError {
  constructor(cause?: unknown) {
    super("Operation timed out", cause);
  }
}

export class InvalidResponseError extends FetchError {
  constructor(
    public statusCode: number,
    public url?: string,
  ) {
    super(`Invalid response from the server, status '${statusCode}'${url != null ? ` (${url})` : ""}`);
  }
}

export class ExternalServerError extends FetchError {
  constructor(
    public statusCode: number,
    public server: string,
    cause?: unknown,
  ) {
    super(`External server error, status '${statusCode}' ${server}`, cause);
  }
}

export class InvalidResourceError extends FetchError {
  constructor(cause?: unknown) {
    super("Received an invalid resource", cause);
  }
}

export class NetworkError extends FetchError {
  constructor(cause?: unknown) {
    super("Server was unreachable", cause);
  }
}

export class MaintenanceModeError extends FetchError {
  constructor() {
    super("Server is in maintenance mode");
  }
}

export class NotFoundError extends FetchError {
  constructor(message: string = "Not Found") {
    super(message);
  }
}

export class CommandInvalidError extends FetchError {
  constructor(message: string) {
    super(message);
  }
}

export class CommandAssertionFailedError extends FetchError {
  constructor(message: string) {
    super(message);
  }
}
